"""Complete nine-body service-evaluation continuation authoring.

Uses the reviewed Build lexical cell/named-function mechanism and the reviewed
Verification DICT_MERGE/DICT_UPDATE policy. The runtime receives no AST.
"""
from __future__ import annotations
import ast
import struct
from types import CodeType
from tools.hia_native_build_control import Compiler as BuildCompiler, Function as BuildFunction
from tools.hia_machine_plan_control import OPS, PACK, COMPARE

METHODS = ("_native", "_build_inputs", "_build_receipt", "_cost_ledger", "_hia_evaluate", "_hia_adopt_native", "invoke_lease")
HELPERS = ("_connection_arguments", "_value_observation")
ENTRIES = METHODS + HELPERS
DICT_UPDATE = 253
MAPPING_PREPARE = 254
MAPPING_CALL = 255


class Compiler(BuildCompiler):
    def __init__(self, source):
        self.source, self.tree = source, ast.parse(source)
        self.lexical_codes = {}
        def remember(code):
            for child in code.co_consts:
                if isinstance(child, CodeType):
                    key = (child.co_firstlineno, child.co_name)
                    if key in self.lexical_codes:
                        raise ValueError('ambiguous evaluation lexical frame')
                    self.lexical_codes[key] = child
                    remember(child)
        remember(compile(source, '<evaluation-lexical-layout>', 'exec'))
        self.imports = {}
        for node in ast.walk(self.tree):
            if isinstance(node, ast.ImportFrom):
                if node.level != 1:
                    raise ValueError('evaluation import must be package-relative')
                self.imports.setdefault(node.module, set()).update(alias.name for alias in node.names)
        self.literals, self.literal_indices = [], {}
        self.functions, self.by_name = [], {}
        classes = [node for node in self.tree.body if isinstance(node, ast.ClassDef)]
        globals_ = [node for node in self.tree.body if isinstance(node, ast.FunctionDef)]
        if (len(classes) != 1 or classes[0].name != 'HIAAgentService'
                or tuple(getattr(node, 'name', None) for node in classes[0].body) != METHODS
                or tuple(node.name for node in globals_) != HELPERS):
            raise ValueError('complete evaluation policy inventory differs')
        for node in [*classes[0].body, *globals_]:
            if not isinstance(node, ast.FunctionDef) or node.decorator_list:
                raise ValueError('evaluation policy declaration differs')
            function = Function(self, node.name, node)
            self.functions.append(function)
            self.by_name[node.name] = function
        index = 0
        while index < len(self.functions):
            self.functions[index].compile()
            index += 1
        for mode, function in enumerate(self.functions, 1):
            function.mode = mode
        for function in self.functions:
            function.resolve()
        self._validate_calls()

    def literal(self, value):
        if type(value) is float:
            # Distinct IEEE payloads, especially +0 and -0, must not collapse
            # under Python's value equality. Each emitted index is boxed once.
            key = (float, struct.pack('<d', value))
            if key not in self.literal_indices:
                self.literal_indices[key] = len(self.literals)
                self.literals.append(value)
            return self.literal_indices[key]
        return super().literal(value)

    def nested(self, parent, node, kind):
        if kind not in ('function', 'generator', 'lambda'):
            raise ValueError('evaluation lexical child kind differs')
        function = Function(self, parent.name + ':' + kind + ':' + str(len(self.functions)),
                            node, parent=parent, kind=kind)
        self.functions.append(function)
        return function


class Function(BuildFunction):
    def expression(self, node):
        if isinstance(node, ast.BoolOp):
            result, done = self.slot(), self.label()
            for index, child in enumerate(node.values):
                self.store(result, self.expression(child))
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(self.copy(result),
                               onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
                    # JUMP_IF_*_OR_POP discards the first value before the
                    # next expression. Keep it only on the short-circuit edge,
                    # where the caller may truth-test that same object again.
                    self.release((result,))
            self.mark(done)
            return result
        if isinstance(node, ast.Call):
            if any(isinstance(arg, ast.Starred) for arg in node.args):
                raise ValueError('evaluation policy has no starred positional call')
            mappings = [i for i, keyword in enumerate(node.keywords) if keyword.arg is None]
            callee = self.expression(node.func)
            arguments = [self.expression(arg) for arg in node.args]
            if mappings:
                if mappings != [len(node.keywords)-1] or len(mappings) != 1:
                    raise ValueError('evaluation mapping must be the one final expansion')
                explicit = node.keywords[:-1]
                if tuple(k.arg for k in explicit) not in ((), ('kind',)):
                    raise ValueError('evaluation explicit mapping-keyword shape differs')
                # CALL_FUNCTION_EX constructs the positional tuple before
                # evaluating the keyword mapping. Its objects then outlive
                # the original operand temporaries under that same tuple.
                positional = self.effect('PACK', raw=(PACK['Tuple'],),
                                         vector=arguments, consume=reversed(arguments))
                values = [self.expression(k.value) for k in explicit]
                mapping = self.expression(node.keywords[-1].value)
                prepared = self.effect('CALL', (callee, positional, *values, mapping),
                    raw=(len(explicit), MAPPING_PREPARE),
                    consume=(*reversed(values), mapping))
                return self.effect('CALL', (callee, positional, prepared),
                                   raw=(0, MAPPING_CALL), consume=(callee, positional, prepared))
            keys = [self.compiler.literal(k.arg) for k in node.keywords]
            values = [self.expression(k.value) for k in node.keywords]
            if len(arguments) > 5 or len(keys) > 8:
                raise ValueError('evaluation fixed call extent differs')
            return self.effect('CALL', (callee, *arguments, *values),
                               raw=(len(arguments), len(keys), *keys),
                               consume=(callee, *arguments, *values))
        if isinstance(node, ast.Dict) and any(key is None for key in node.keys):
            result = self.effect('PACK', raw=(PACK['Dict'],), vector=())
            pending_keys, pending_values = [], []
            def flush():
                if pending_keys:
                    block = super(Function, self).expression(ast.Dict(
                        keys=list(pending_keys), values=list(pending_values)))
                    self.effect('CALL', (result, block), raw=(0, DICT_UPDATE),
                                destination=result, consume=(block,))
                    pending_keys.clear(); pending_values.clear()
            for key, value in zip(node.keys, node.values):
                if key is None:
                    flush()
                    mapping = self.expression(value)
                    self.effect('CALL', (result, mapping), raw=(0, DICT_UPDATE),
                                destination=result, consume=(mapping,))
                else:
                    if not isinstance(key, ast.Constant) or type(key.value) is not str:
                        raise ValueError('evaluation expanded dictionary key shape differs')
                    pending_keys.append(key); pending_values.append(value)
            flush()
            return result
        return super().expression(node)



def compile_policy(source):
    return Compiler(source)

"""Generate complete Agent evaluation/adoption/lease HIA policy."""
from __future__ import annotations

import argparse
import ast
from pathlib import Path
import sys
import struct

ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.generate_hia_machine_plan_control import (
    BODY as CONTROL_BODY, MAGIC, EMIT_MAGIC, ABI, OUTPUT)
from tools.generate_hia_core_lowering import emission, transport_helpers
from tools.hia_core_lowering_table import BODY as EXPAND_BODY, compress_table, reference_expand
from tools.hia_exception_delivery import BODY as EXCEPTION_BODY
from tools.hia_service_evaluation_control import compile_policy, OPS


def table(policy):
    starts = {}
    count = 0
    for function in policy.functions:
        starts[function.mode] = count + 1
        count += len(function.instructions)
    data = bytearray(64 + len(policy.functions) * 32)
    for function in policy.functions:
        metadata = len(data)
        data += bytes((int(i in function.temporary_slots) |
                       (2 * int(i in function.cell_slots)))
                      for i in range(function.next_slot))
        for own, outer in function.captures.values():
            data += struct.pack('<H', own.slot)
        info = (len(function.parameters) |
                (int(function.kind == 'generator') << 16) |
                (len(function.captures) << 32))
        struct.pack_into('<4Q', data, 64 + (function.mode - 1) * 32,
                         starts[function.mode], function.next_slot, info, metadata)
    offsets_at = len(data)
    data += b'\0' * (4 * count)
    ordinal = 0
    for function in policy.functions:
        shift = starts[function.mode] - 1
        for instruction in function.instructions:
            struct.pack_into('<I', data, offsets_at + ordinal * 4, len(data))
            ordinal += 1
            kind = instruction['kind']
            if kind == 'effect':
                destinations, arguments = instruction['destinations'], instruction['arguments']
                raw, vector = instruction['raw'], instruction['vector']
                consume = instruction['consume']
                handler = instruction['handler']
                data += struct.pack('<6BH I H', 1, instruction['opcode'], len(destinations),
                                    len(arguments), len(raw), len(consume), len(vector),
                                    handler + shift if handler else 0, 0)
                for ref in (*destinations, *arguments):
                    data += struct.pack('<H', ref.slot)
                for value in raw:
                    data += struct.pack('<I', value)
                for ref in (*vector, *consume):
                    data += struct.pack('<H', ref.slot)
            elif kind == 'jump':
                data += struct.pack('<BI', 2, instruction['target'] + shift)
            elif kind == 'flag':
                data += struct.pack('<BII', 3, instruction['yes'] + shift,
                                    instruction['no'] + shift)
            elif kind in ('return', 'yield'):
                data += struct.pack('<BH', 4 if kind == 'return' else 5,
                                    instruction['value'].slot)
            elif kind == 'error_return':
                data += b'\6'
            else:
                raise ValueError('unrendered instruction')
    literals_at = len(data)
    data += b'\0' * (4 * len(policy.literals))
    for index, value in enumerate(policy.literals):
        struct.pack_into('<I', data, literals_at + 4 * index, len(data))
        if value is None:
            kind, raw = 0, b''
        elif type(value) is bool:
            kind, raw = 1, bytes((int(value),))
        elif type(value) is int:
            kind, raw = 2, str(value).encode('ascii')
        elif type(value) is bytes:
            kind, raw = 5, value
        elif type(value) is float:
            kind, raw = 6, struct.pack('<d', value)
        elif type(value) is str:
            # CPython interns its ASCII name-character constants. Record that
            # representation in the immutable HIA-owned table, so the runtime
            # bridge does not infer a policy or change the object's identity.
            interned = all(c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
                           for c in value)
            kind, raw = (4 if interned else 3), value.encode('utf-8')
        else:
            raise ValueError('unrendered literal')
        data += struct.pack('<BQ', kind, len(raw)) + raw
    data += bytes((-len(data)) % 8)
    struct.pack_into('<8Q', data, 0, MAGIC, len(data), len(policy.functions), count,
                     64, offsets_at, literals_at, len(policy.literals))
    return bytes(data)


def program():
    return compile_policy((ROOT / 'tools/hia_service_evaluation_policy.py').read_text())


def source():
    policy = program()
    data = table(policy)
    packed = compress_table(data)
    if reference_expand(packed) != data:
        raise AssertionError('service-evaluation policy representation is not lossless')
    constants = {'MAGIC': MAGIC, 'EMIT_MAGIC': EMIT_MAGIC, 'ABI': ABI,
                 'OUTPUT_BYTES': OUTPUT, 'TABLE_BYTES': len(data),
                 'PACKED_BYTES': len(packed),
                 'WORKSPACE_BYTES': 1024 + 8 * max(fn.next_slot for fn in policy.functions),
                 **OPS}
    parsed = ast.parse(CONTROL_BODY + '\n' + transport_helpers() + '\n' +
                       emission(data, packed) + '\n' + EXPAND_BODY + '\n' + EXCEPTION_BODY)
    class Names(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.copy_location(ast.Constant(constants[node.id]), node) if node.id in constants else node
    return ast.fix_missing_locations(Names().visit(parsed))


def document():
    nodes = source().body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args], node.returns.id)
                  for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name], 'params': [builder.param(v) for v in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                  'module': 'service_evaluation', 'functions': functions})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path,
                        default=ROOT / 'examples/hia_bootstrap/service_evaluation.hiaasm')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raw = render_assembly(document()).encode()
    if args.check:
        if args.output.read_bytes() != raw:
            raise AssertionError('service-evaluation HIA differs from its complete policy')
    else:
        args.output.write_bytes(raw)
    print(args.output)


if __name__ == '__main__':
    main()

"""HIA-owned Agent evaluation coordination with fixed object/effect ports.

The image owns all nine retained policy bodies, including lexical closures,
helper selection, ordered budget claims and publication. Python supplies fixed
object, import, mapping and exception primitives. Storage, SQL, clocks, runner,
proof, emission and compiler subowners remain separately declared providers.
"""
from __future__ import annotations

import builtins
from contextvars import ContextVar
from functools import lru_cache
from hashlib import sha256
import json
import os
from pathlib import Path
import stat
import struct
import sys

from .hia_json_preflight_native import _source_resource_path
from .hia_machine_plan_control_native import (
    PlanFrame, NativeMachinePlanControl, _Cell, _EMPTY,
    Issued, _read_word, _capture_with_handler)
from . import hia_service_evaluation_foreign as foreign

SOURCE = _source_resource_path('examples/hia_bootstrap/service_evaluation.hiaasm')
SCHEMA = 'hepta.hia.service-evaluation-native.v1'
SELECTOR = 'HEPTA_HIA_SERVICE_EVALUATION_MANIFEST'
ARITIES = {
    '_native': 4, '_build_inputs': 5, '_build_receipt': 5,
    '_cost_ledger': 4, '_hia_evaluate': 2, '_hia_adopt_native': 3,
    'invoke_lease': 4, '_connection_arguments': 1, '_value_observation': 1,
}
_IMPORTS = {
    'hia_agent_runner': frozenset(('run_native_batch', 'run_reference_batch')),
    'hia_agent_buffers': frozenset(('validate_cases', 'validate_arguments')),
}
_ACTIVE = ContextVar('hia_service_evaluation_owner', default=None)
_UNCONFIRMED_IMAGE_CLEANUP = []


class EvaluationUnknown(RuntimeError):
    """A native/effect handoff is unconfirmed; no permission is recreated."""


def _manifest_pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate service-evaluation manifest field')
        result[key] = value
    return result


def _regular_bytes(path, limit):
    descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, 'rb') as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= limit:
            raise ValueError('service-evaluation input must be a bounded ordinary file')
        raw = stream.read(limit + 1)
        after = os.fstat(stream.fileno())
    fields = ('st_dev', 'st_ino', 'st_size', 'st_mtime_ns', 'st_ctime_ns')
    if len(raw) != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields):
        raise ValueError('service-evaluation input changed while being read')
    return raw


@lru_cache(maxsize=3)
def _mapped_evaluation(raw, expected):
    return NativeEvaluationImage(raw, expected)


def installed_evaluation(manifest_path, *, capture_identity=False):
    """Fresh admission; later execution retains this actual immutable mapping.

    An active worker bundle is authoritative. The cache shares only immutable
    executable bytes, never an admission decision or a mutable file snapshot.
    Each returned checker capability owns its exact source/manifest bytes.
    """
    from .hia_native_helpers import pinned_image
    selected = pinned_image(manifest_path, SOURCE, SCHEMA, NativeEvaluationImage)
    path = Path(manifest_path).resolve(strict=True)
    raw = _regular_bytes(path, 16384)
    value = json.loads(raw, object_pairs_hook=_manifest_pairs)
    fields = {'schema', 'source_sha256', 'image_path', 'image_sha256', 'compiler_sha256'}
    if (type(value) is not dict or set(value) != fields or value['schema'] != SCHEMA
            or any(type(value[key]) is not str or len(value[key]) != 64
                   or any(char not in '0123456789abcdef' for char in value[key])
                   for key in ('source_sha256', 'image_sha256', 'compiler_sha256'))):
        raise ValueError('invalid service-evaluation manifest')
    name = value['image_path']
    if (type(name) is not str or not name or name in ('.', '..')
            or any(ord(char) < 32 for char in name) or Path(name).name != name):
        raise ValueError('service-evaluation image must be a sibling basename')
    source_raw = _regular_bytes(SOURCE, 8 << 20)
    if sha256(source_raw).hexdigest() != value['source_sha256']:
        raise ValueError('service-evaluation source identity mismatch')
    image_path = path.parent / name
    image_raw = _regular_bytes(image_path, 1 << 20)
    if sha256(image_raw).hexdigest() != value['image_sha256']:
        raise ValueError('service-evaluation image identity mismatch')
    if selected is None:
        selected = _mapped_evaluation(image_raw, value['image_sha256'])
    elif type(selected) is not NativeEvaluationImage or selected.image_sha256 != value['image_sha256']:
        raise ValueError('service-evaluation mapping differs from its pinned worker image')
    if (_regular_bytes(path, 16384) != raw or _regular_bytes(SOURCE, 8 << 20) != source_raw
            or _regular_bytes(image_path, 1 << 20) != image_raw):
        raise ValueError('service-evaluation selection changed during admission')
    if capture_identity:
        from .hia_checker_identity import hold_native_owner
        return hold_native_owner(SELECTOR, selected, raw, source_raw)
    return selected


def admitted_evaluation(*, capture_identity=False):
    selected = os.environ.get(SELECTOR)
    if not selected:
        return None
    return installed_evaluation(selected, capture_identity=capture_identity)


def _match_exception(frame, slot):
    # This invokes the interpreter's real exception matching, not isinstance
    # (which has different metaclass behavior and accepts non-exception types).
    # No borrowed error or match type is saved in a transport named local.
    try:
        frame.image._delivery.deliver(frame.error)
    except frame._get(slot) as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 1
    except BaseException as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 0
    frame._uncertain = True
    raise EvaluationUnknown('evaluation exception delivery returned')


class EvaluationFrame(PlanFrame):
    def _global(self, name):
        namespace = self.image.namespace
        if name in self.image._helpers:
            current = namespace.get(name, _EMPTY)
            if current is self.image.public_helpers[name]:
                return self.image._helpers[name]
            if current is not _EMPTY:
                return current
        if name in namespace:
            return namespace[name]
        if name in vars(builtins):
            return vars(builtins)[name]
        raise NameError("name '" + name + "' is not defined", name=name)

    def _move(self, slot):
        value = self._get(slot)
        self._clear(slot)
        return value

    def _load_named(self, slot, name, role):
        if type(slot) is not int or not 0 <= slot < len(self.values):
            raise EvaluationUnknown('evaluation named slot is outside its frame')
        value = self.values[slot]
        if slot in self.cells:
            value = value.value
        if value is _EMPTY:
            return foreign.unbound(name, role)
        return value

    def _call(self, args, raw):
        if raw == (0, 253):
            if len(args) != 2 or type(self._get(args[0])) is not dict:
                raise EvaluationUnknown('evaluation dictionary-update ABI differs')
            return foreign.update_dict(self, args[0], args[1])
        if raw in ((0, 254), (1, 254)):
            if len(args) != 3 + raw[0] or type(self._get(args[1])) is not tuple:
                raise EvaluationUnknown('evaluation mapping-prepare ABI differs')
            if raw[0] == 0:
                return foreign.merge_empty(self, *args)
            return foreign.merge_kind(self, *args)
        if raw == (0, 255):
            if len(args) != 3:
                raise EvaluationUnknown('evaluation mapping-call ABI differs')
            return foreign.mapping_call(self, *args)
        if len(raw) < 2 or len(raw) != 2 + raw[1] or len(args) != 1 + raw[0] + raw[1]:
            raise EvaluationUnknown('evaluation ordinary-call ABI differs')
        key = (raw[0], tuple(self.image.literal(index) for index in raw[2:]))
        call = foreign.CALLS.get(key)
        if call is None:
            raise EvaluationUnknown('evaluation call shape is outside the fixed policy')
        return call(self, args)

    def _function(self, args, raw, vector):
        if len(raw) != 2:
            raise EvaluationUnknown('evaluation closure representation differs')
        mode, generator = raw
        if generator not in (0, 1) or len(args) != generator:
            raise EvaluationUnknown('evaluation closure entry representation differs')
        layout = self.image.layouts.get(mode)
        if layout is None or (layout[1] == 'generator') != bool(generator):
            raise EvaluationUnknown('evaluation closure mode differs')
        captures = tuple(self.values[slot] for slot in vector)
        if len(captures) != layout[4] or any(type(cell) is not _Cell for cell in captures):
            raise EvaluationUnknown('evaluation captured a non-cell or wrong closure')
        if generator:
            frame = EvaluationFrame(self.image, mode, (self._get(args[0]),), captures,
                                    witness=self.witness)
            def native_generator():
                value = None
                try:
                    while True:
                        value = None
                        if frame.drive() == 0:
                            return
                        value = frame.take(yielded=True)
                        yield value
                finally:
                    value = None
            return native_generator()
        image, witness = self.image, self.witness
        def native_function(*arguments):
            frame = EvaluationFrame(image, mode, arguments, captures, witness=witness)
            arguments = None
            return image.finish(frame)
        return native_function

    def _effect(self):
        op, destinations, args, raw, vector = self._parts()
        if op == 13 and raw == (4,):
            if len(destinations) != 4 or len(args) != 1 or vector:
                raise EvaluationUnknown('evaluation four-value unpack representation differs')
            first, second, third, fourth = self._get(args[0])
            self._set(destinations[0], first)
            self._set(destinations[1], second)
            self._set(destinations[2], third)
            self._set(destinations[3], fourth)
            first = second = third = fourth = None
            return 0
        if op == 19:
            if len(raw) < 2 or len(destinations) != 1 or vector:
                raise EvaluationUnknown('evaluation import representation differs')
            if raw[0] == 0 and not args:
                module = self.image.literal(raw[1])
                names = tuple(self.image.literal(index) for index in raw[2:])
                if module not in _IMPORTS or any(name not in _IMPORTS[module] for name in names):
                    raise EvaluationUnknown('evaluation import is outside fixed ports')
                port = self.image._import_names.get((module, names))
                if port is None:
                    raise EvaluationUnknown('evaluation import group differs')
                self._set(destinations[0], port())
            elif raw[0] == 1 and len(raw) == 2 and len(args) == 1:
                name = self.image.literal(raw[1])
                port = self.image._import_from.get(name)
                if port is None:
                    raise EvaluationUnknown('evaluation imported field differs')
                self._set(destinations[0], port(self._get(args[0])))
            else:
                raise EvaluationUnknown('evaluation import phase differs')
            return 0
        if op == 15 and raw:
            if len(raw) != 2 or len(args) != 1 or len(destinations) != 1 or vector:
                raise EvaluationUnknown('evaluation named-load representation differs')
            self._set(destinations[0], self._load_named(args[0], self.image.literal(raw[0]), raw[1]))
            return 0
        if op == 21:
            if len(args) != 1 or destinations or raw or vector:
                raise EvaluationUnknown('evaluation exception matcher representation differs')
            return _match_exception(self, args[0])
        return super()._effect()

    def service(self, issued):
        # Same issued-object/native-preclaim protocol as the frozen Plan
        # engine. The additional flag prevents a failing physical exception
        # mechanism from being acknowledged as a known foreign policy error.
        if (self.closed and not self._retiring) or issued is not self.pending or type(issued) is not Issued:
            raise EvaluationUnknown('evaluation observation is not the issued permission')
        if type(issued.raw) is not bytes or issued.raw != self.frame_bytes or self.executed:
            raise EvaluationUnknown('evaluation observation changed or was consumed')
        self.executed = True
